package com.andye.warmod.warhead;
import com.andye.warmod.entity.IncomingWarheadEntity;import java.util.*;import net.minecraft.server.level.ServerLevel;
public final class IncomingWarheadRegistry{private static final Map<ServerLevel,Map<UUID,LinkedHashMap<UUID,IncomingWarheadEntity>>> ACTIVE=new WeakHashMap<>();private IncomingWarheadRegistry(){}public static synchronized void register(ServerLevel level,IncomingWarheadEntity entity){UUID root=entity.radarRootTrackId(),id=entity.warheadId();if(root!=null&&id!=null&&!entity.isRemoved())ACTIVE.computeIfAbsent(level,x->new HashMap<>()).computeIfAbsent(root,x->new LinkedHashMap<>()).put(id,entity);}public static synchronized Optional<IncomingWarheadEntity> get(ServerLevel level,UUID root){return getAllForRoot(level,root).stream().findFirst();}public static synchronized Optional<IncomingWarheadEntity> getByWarheadId(ServerLevel level,UUID id){Map<UUID,LinkedHashMap<UUID,IncomingWarheadEntity>> roots=ACTIVE.get(level);if(roots==null)return Optional.empty();for(var children:roots.values()){IncomingWarheadEntity entity=children.get(id);if(entity!=null&&!entity.isRemoved())return Optional.of(entity);}return Optional.empty();}public static synchronized List<IncomingWarheadEntity> getAllForRoot(ServerLevel level,UUID root){var roots=ACTIVE.get(level);var children=roots==null?null:roots.get(root);if(children==null)return List.of();children.values().removeIf(e->e==null||e.isRemoved());return List.copyOf(children.values());}public static synchronized List<IncomingWarheadEntity> activeWarheads(ServerLevel level){var roots=ACTIVE.get(level);if(roots==null)return List.of();ArrayList<IncomingWarheadEntity> out=new ArrayList<>();for(UUID root:List.copyOf(roots.keySet()))out.addAll(getAllForRoot(level,root));return List.copyOf(out);}public static synchronized void unregister(ServerLevel level,UUID root,UUID warhead){var roots=ACTIVE.get(level);if(roots==null)return;var children=roots.get(root);if(children!=null){children.remove(warhead);if(children.isEmpty())roots.remove(root);}if(roots.isEmpty())ACTIVE.remove(level);}public static synchronized void unregister(ServerLevel level,UUID root){cancelAllForRoot(level,root);}public static synchronized void cancelAllForRoot(ServerLevel level,UUID root){var roots=ACTIVE.get(level);if(roots!=null){roots.remove(root);if(roots.isEmpty())ACTIVE.remove(level);}}public static synchronized void clearAll(){ACTIVE.clear();}}
